def sum_digits(n):
    """Calculates the sum of the digits of a positive integer n."""
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    """Checks if S(n)S(n+1)...S(n+37) is not a multiple of 11."""
    for k in range(38):
        number = n + k
        s_value = sum_digits(number)
        if s_value % 11 == 0:
            return False # Found a multiple of 11
    return True # None of the 38 were a multiple of 11

